            print("Invalid reading, aborting.")
            return 1

        for dev, pin in zip(devices, PINS):
            apply_state(pin, VALID_READING / 100.0)
        return 0

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass


