import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUDRATE = 9600
TIMEOUT_S = 1.0
POLL_INTERVAL_S = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port():
    try:
        return serial.Serial(
            PORT,
            BAUDRATE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return None


def read_device_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None

    if not raw:
        print("Warning: no response from device within timeout.", file=sys.stderr)
        return None

    try:
        data = raw.decode("utf-8", errors="replace").strip()
    except Exception as exc:
        print(f"Error: decode failed: {exc}", file=sys.stderr)
        return None

    if not data:
        return None

    if not validate_data(data):
        print(f"Warning: invalid data received: {data!r}", file=sys.stderr)
        return None

    return data


def validate_data(data):
    if not data or not data.isprintable():
        return False
    return True


def process_data(data):
    print(f"Received data: {data}")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            data = read_device_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed.")


if __name__ == "__main__":
    main()

