import signal
import sys
import time

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN = 17
INTERVAL = 2.0
POLL_TIMEOUT = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        led = DigitalOutputDevice(PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    print(f"GPIO {PIN} initialized as output (active_high=True).")

    try:
        while _running:
            try:
                led.on()
                print("GPIO 17 set to HIGH")
            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error writing HIGH: {exc}", file=sys.stderr)
                break

            if not _wait(INTERVAL):
                break

            try:
                led.off()
                print("GPIO 17 set to LOW")
            except DeviceClosed:
                print("Device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error writing LOW: {exc}", file=sys.stderr)
                break

            if not _wait(INTERVAL):
                break
    finally:
        try:
            led.close()
            print("GPIO 17 released.")
        except Exception:
            pass

    print("Program finished.")
    return 0


def _wait(duration):
    """Sleep in small increments so signals are caught promptly."""
    end = time.monotonic() + duration
    while _running and time.monotonic() < end:
        time.sleep(min(0.1, end - time.monotonic()))
    return _running


if __name__ == "__main__":
    sys.exit(main())

import serial
import signal
import sys

PORT = "/dev/serial0"
BAUDRATE = 9600
TIMEOUT_S = 2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def is_valid(reading: str) -> bool:
    """Return True when *reading* passes the validity check."""
    return bool(reading.strip())


def process_reading(reading: str) -> None:
    """Print the validated reading to stdout."""
    print(f"Validated data: {reading}", flush=True)


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(PORT, BAUDRATE, timeout=TIMEOUT_S)
        print(f"Opened {PORT} @ {BAUDRATE} baud", flush=True)

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr, flush=True)
                break

            if not raw:
                # Timed out waiting for data — device may be absent or unresponsive.
                continue

            line = raw.decode("utf-8", errors="replace").strip()
            if not line:
                continue

            if is_valid(line):
                process_reading(line)
            else:
                print("Invalid data received, discarding.", flush=True)

    except serial.SerialException as exc:
        print(f"Failed to open serial port {PORT}: {exc}", file=sys.stderr, flush=True)
        return 1
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.", flush=True)

    return 0


if __name__ == "__main__":
    sys.exit(main())

