import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN = 17
INTERVAL = 60
TIMEOUT = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _check_validity(value: int) -> bool:
    return value in (0, 1)


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dev = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                dev.on()
                value = 1
            except DeviceClosed:
                print("Error: device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error: failed to write to GPIO {PIN}: {exc}", file=sys.stderr)
                break

            if not _check_validity(value):
                print(f"Error: invalid reading from GPIO {PIN}.", file=sys.stderr)
                break

            print(f"GPIO {PIN} set to {value}")

            elapsed = 0.0
            while _running and elapsed < INTERVAL:
                time.sleep(0.5)
                elapsed += 0.5

    finally:
        try:
            dev.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
WHO_AM_I_REG = 0x75
WHO_AM_I_EXPECTED = 0x68
PWR_MGMT_1_REG = 0x6B
ACCEL_XOUT_H_REG = 0x3B

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

def read_word(bus, addr, reg):
    """Read a big-endian 16-bit word starting at `reg`."""
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    data = list(read_msg)
    if len(data) < 2:
        raise IOError(f"Short read from register 0x{reg:02X}")
    return (data[0] << 8) | data[1]

def main():
    bus = None
    try:
        bus = SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus /dev/i2c-1 not found. Enable I2C with `sudo raspi-config`.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied opening /dev/i2c-1. Add user to the 'i2c' group or run with appropriate privileges.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error opening I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device with a quick read of WHO_AM_I.
        try:
            who_am_i = bus.read_byte_data(MPU6050_ADDR, WHO_AM_I_REG)
        except OSError as e:
            print(f"Error: No device found at address 0x{MPU6050_ADDR:02X} ({e}).", file=sys.stderr)
            sys.exit(1)

        if who_am_i != WHO_AM_I_EXPECTED:
            print(f"Warning: WHO_AM_I mismatch (got 0x{who_am_i:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}). Continuing anyway.", file=sys.stderr)

        # Wake up the MPU6050 by clearing the SLEEP bit in PWR_MGMT_1.
        try:
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1_REG, 0x00)
        except OSError as e:
            print(f"Error: Failed to configure PWR_MGMT_1: {e}", file=sys.stderr)
            sys.exit(1)

        # Allow sensors to settle after wake-up.
        import time
        time.sleep(0.1)

        # Read one sample.
        try:
            accel_x = read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H_REG)
            print(f"Accel X: {accel_x}")
        except OSError as e:
            print(f"Error: Failed to read accelerometer data: {e}", file=sys.stderr)
            sys.exit(1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

