TRIGGER_PIN = 17
MAX_DISTANCE_M = 2.0          # HC-SR04 practical max (~2 m)
TIMEOUT_S = 1.0               # Give up if no echo within this window
POLL_INTERVAL_S = 0.05        # Small delay between attempts


def measure_distance(sensor):
    """Return distance in metres, or None on timeout / error."""
    try:
        sensor.trigger()
    except (GPIOZeroError, DeviceClosed) as exc:
        print(f"Trigger failed: {exc}", file=sys.stderr)
        return None

    deadline = time.monotonic() + TIMEOUT_S
    while time.monotonic() < deadline:
        try:
            dist = sensor.distance
        except (GPIOZeroError, DeviceClosed) as exc:
            print(f"Read failed: {exc}", file=sys.stderr)
            return None
        if dist is not None and dist > 0:
            return dist
        time.sleep(POLL_INTERVAL_S)
    return None


def main():
    sensor = None
    try:
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    def cleanup(signum=None, frame=None):
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        distance = measure_distance(sensor)
        if distance is None:
            print("Distance measurement failed or timed out.")
        else:
            print(f"Measured Distance = {distance:.3f} m")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

import signal
import sys
import time

import board
import busio
import digitalio
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

# --- Configuration -----------------------------------------------------------
CHANNEL = 0          # MCP3008 single-ended channel 0
SAMPLES = 10         # Number of readings to take
SAMPLE_INTERVAL_S = 60  # Delay between readings (seconds)
SPI_TIMEOUT_S = 5    # SPI read/write deadline in seconds

# --- Globals for cleanup -----------------------------------------------------
_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _install_signal_handlers():
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, _handle_signal)


def _open_spi():
    """Open the SPI bus and MCP3008, raising on failure."""
    spi = busio.SPI(clock=board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    cs = digitalio.DigitalInOut(board.D5)  # CS on GPIO5 (physical pin 29)
    mcp = MCP3008(spi, cs)
    return mcp


def _read_channel(mcp, channel):
    """Return a single AnalogIn reading or None on transient error."""
    try:
        return AnalogIn(mcp, channel)
    except Exception as exc:
        print(f"[WARN] Failed to read channel {channel}: {exc}", file=sys.stderr)
        return None


def main():
    _install_signal_handlers()

    try:
        mcp = _open_spi()
    except Exception as exc:
        print(f"[ERROR] Cannot open SPI/MCP3008: {exc}", file=sys.stderr)
        sys.exit(1)

    completed = 0
    while _running and completed < SAMPLES:
        reading = _read_channel(mcp, CHANNEL)
        if reading is not None:
            try:
                voltage = reading.voltage
                print(f"Reading {completed + 1}/{SAMPLES}: {voltage:.4f} V")
                completed += 1
            except Exception as exc:
                print(f"[WARN] Voltage read failed: {exc}", file=sys.stderr)
        else:
            print("[WARN] Skipping sample due to read error.", file=sys.stderr)

        if _running and completed < SAMPLES:
            # Interruptible sleep so signals are handled promptly.
            end_time = time.monotonic() + SAMPLE_INTERVAL_S
            while _running and time.monotonic() < end_time:
                time.sleep(0.1)

    print(f"\nCompleted {completed} of {SAMPLES} readings.")


if __name__ == "__main__":
    main()

