import serial
import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
TIMEOUT_S = 1.0
MAX_READINGS = 1


class SerialReader:
    def __init__(self, port=PORT, baudrate=BAUDRATE, timeout=TIMEOUT_S):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def open(self):
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout,
            )
        except serial.SerialException as exc:
            print(f"Error opening serial port {self.port}: {exc}", file=sys.stderr)
            raise

    def read_once(self):
        if self.ser is None or not self.ser.is_open:
            print("Serial port is not open.", file=sys.stderr)
            return False

        try:
            raw = self.ser.readline()
        except serial.SerialException as exc:
            print(f"Error reading from serial port: {exc}", file=sys.stderr)
            return False

        if not raw:
            print("No data received (timeout).", file=sys.stderr)
            return False

        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            print("Empty line received.", file=sys.stderr)
            return False

        try:
            value = float(line)
        except ValueError:
            print(f"Invalid data received (not numeric): '{line}'", file=sys.stderr)
            return False

        if not (-273.15 <= value <= 1000.0):
            print(f"Value out of range: {value}", file=sys.stderr)
            return False

        print(f"Valid reading: {value}")
        return True

    def close(self):
        if self.ser is not None and self.ser.is_open:
            try:
                self.ser.close()
            except serial.SerialException as exc:
                print(f"Error closing serial port: {exc}", file=sys.stderr)

    def run(self):
        self.open()
        try:
            success = self.read_once()
            return 0 if success else 1
        finally:
            self.close()


def main():
    reader = SerialReader()
    try:
        return reader.run()
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        return 130
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())

