import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin mapping for the HC-SR04 ultrasonic sensor.
ECHO_PIN = 18
TRIGGER_PIN = 23
MAX_DISTANCE_M = 2.0          # HC-SR04 practical max ~4 m; 2 m is safe
TIMEOUT_S = 1.0               # fail-fast timeout if no echo
POLL_INTERVAL_S = 0.05        # polling cadence


def measure_distance(sensor):
    """Return distance in metres, or None on timeout / error."""
    try:
        # gpiozero DistanceSensor exposes distance in metres (0..max_distance).
        distance = sensor.distance
        if distance is None or distance >= MAX_DISTANCE_M:
            return None
        return round(distance, 3)
    except (GPIOZeroError, DeviceClosed) as exc:
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return None


def main():
    # Graceful shutdown flag.
    running = True

    def _shutdown(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    sensor = None
    try:
        # gpiozero handles trigger / echo timing internally.
        sensor = DistanceSensor(
            echo=ECHO_PIN,
            trigger=TRIGGER_PIN,
            max_distance=MAX_DISTANCE_M,
        )
        deadline = time.monotonic() + TIMEOUT_S

        while running and time.monotonic() < deadline:
            distance = measure_distance(sensor)
            if distance is not None:
                print(f"Distance: {distance} m")
                return
            time.sleep(POLL_INTERVAL_S)

        if running:
            print("Timeout: no valid echo received.", file=sys.stderr)
            sys.exit(1)

    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

