import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
TIMEOUT_S = 1.0
POLL_INTERVAL_S = 0.05
MAX_RETRIES = 3

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def open_serial_port():
    """Open the serial port with robust error handling."""
    try:
        return serial.Serial(
            port=PORT,
            baudrate=BAUDRATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: device unavailable {PORT}: {exc}", file=sys.stderr)
        return None


def read_data(ser):
    """Read one line from the serial port; return None on transient failure."""
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('utf-8', errors='replace').strip()
    except serial.SerialException as exc:
        print(f"Warning: read error: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Warning: OS-level read error: {exc}", file=sys.stderr)
        return None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    consecutive_errors = 0
    try:
        while running:
            data = read_data(ser)
            if data:
                print(data)
                consecutive_errors = 0
            else:
                consecutive_errors += 1
                if consecutive_errors >= MAX_RETRIES:
                    print("Error: no response from device after retries.", file=sys.stderr)
                    break

            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            if ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception:
            pass


