import time
import signal
import sys

try:
    import board
    import adafruit_dht
except ImportError:
    print("Missing dependency: install adafruit-circuitpython-dht and libgpiod", file=sys.stderr)
    sys.exit(1)

PINS = [board.D4, board.D7, board.D11, board.D17]
READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(sensor):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            t = sensor.temperature
            h = sensor.humidity
            if t is None or h is None:
                raise RuntimeError("Sensor returned None")
            return t, h
        except Exception as exc:
            print(f"  Read attempt {attempt}/{MAX_RETRIES} failed: {exc}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None, None


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensors = []
    for pin in PINS:
        try:
            s = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(s)
        except Exception as exc:
            print(f"Failed to initialize DHT22 on {pin}: {exc}", file=sys.stderr)
            for s in sensors:
                try:
                    s.exit()
                except Exception:
                    pass
            sys.exit(1)

    print("DHT22 monitoring started on pins:", [p.name for p in PINS])
    print("Press Ctrl+C to stop.\n")

    try:
        while _running:
            readings = {}
            for idx, s in enumerate(sensors):
                t, h = read_sensor(s)
                if t is not None and h is not None:
                    readings[PINS[idx]] = (t, h)
                else:
                    print(f"  Pin {PINS[idx].name}: read failed after retries")

            if readings:
                for pin, (temp, hum) in readings.items():
                    print(f"Pin {pin.name}: T={temp:.1f}C  H={hum:.1f}%")
            else:
                print("No valid readings from any sensor.")

            print("-" * 40)

            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        for s in sensors:
            try:
                s.exit()
            except Exception:
                pass
        print("\nResources released. Exiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [4, 5, 6, 13, 17, 22, 27]
DELAY = 0.01
MAX_RETRIES = 1000

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                raise

        count = 0
        while _running and count < MAX_RETRIES:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set HIGH")
                except DeviceClosed:
                    print("Device closed unexpectedly", file=sys.stderr)
                    return 1
                except GPIOZeroError as exc:
                    print(f"Error writing GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                    return 1

            time.sleep(DELAY)
            count += 1

        if count >= MAX_RETRIES:
            print("Max retries reached without interruption.", file=sys.stderr)
            return 1

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

