import time
import signal
import sys

try:
    import board
    import busio
    from adafruit_mcp3xxx.mcp3008 import MCP3008
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
ADC_CHANNEL = 0          # MCP3008 single-ended channel 0
READING_COUNT = 5        # Total readings to take
DELAY_SECONDS = 300      # Delay between readings
TIMEOUT_SECONDS = 5      # SPI read timeout so we don't hang forever

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def _read_adc(mcp):
    """
    Read one channel from the MCP3008.

    Returns the raw 10-bit value (0-1023) or None on failure.
    """
    try:
        return mcp.read(ADC_CHANNEL)
    except Exception as exc:
        print(f"Error reading ADC channel {ADC_CHANNEL}: {exc}", file=sys.stderr)
        return None


def main():
    # --- Hardware initialization --------------------------------------------
    spi = None
    cs = None
    mcp = None

    try:
        spi = busio.SPI(clock=board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        spi.try_lock()
        spi.configure(baudrate=1_000_000, phase=0, polarity=0)
        spi.unlock()

        cs = digitalio.DigitalInOut(board.D5)   # CE0 / CS pin
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True                          # Idle high

        mcp = MCP3008(spi, cs)
        print("MCP3008 initialized successfully.")

    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        if spi is not None:
            try:
                spi.deinit()
            except Exception:
                pass
        if cs is not None:
            try:
                cs.deinit()
            except Exception:
                pass
        sys.exit(1)

    # --- Sampling loop ------------------------------------------------------
    completed = 0
    try:
        while _running and completed < READING_COUNT:
            reading = _read_adc(mcp)

            if reading is None:
                print("ADC reading failed; aborting.", file=sys.stderr)
                break

            if not isinstance(reading, int) or not (0 <= reading <= 1023):
                print(f"Invalid ADC reading: {reading!r}; skipping.", file=sys.stderr)
                time.sleep(DELAY_SECONDS)
                continue

            print(f"Reading {completed + 1}/{READING_COUNT}: {reading}")
            completed += 1

            if _running and completed < READING_COUNT:
                # Interruptible sleep
                end_time = time.monotonic() + DELAY_SECONDS
                while _running and time.monotonic() < end_time:
                    time.sleep(0.1)

    finally:
        # --- Clean resource release on all exit paths -----------------------
        if mcp is not None:
            try:
                mcp.close()
            except Exception:
                pass
        if cs is not None:
            try:
                cs.deinit()
            except Exception:
                pass
        if spi is not None:
            try:
                spi.deinit()
            except Exception:
                pass
        print("Resources released.")


if __name__ == "__main__":
    main()

