import serial
import time
import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
TIMEOUT_S = 1.0
POLL_INTERVAL_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port():
    try:
        return serial.Serial(
            PORT,
            BAUDRATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return None


def read_data(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Error: decode failed: {exc}", file=sys.stderr)
        return None


def validate(data):
    if not data:
        return False
    if not data.isdigit():
        print(f"Invalid data received (not numeric): {data!r}", file=sys.stderr)
        return False
    value = int(data)
    if value < 0 or value > 100:
        print(f"Invalid data received (out of range): {value}", file=sys.stderr)
        return False
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            data = read_data(ser)
            if data is not None and validate(data):
                print(f"Received valid data: {data}")
            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed.")


if __name__ == '__main__':
    main()

