import time
import signal
import sys
from smbus2 import SMBus

I2C_BUS = 1
BMP280_ADDR = 0x76
REG_ID = 0xD0
REG_RESET = 0xE0
REG_CTRL_MEAS = 0xF4
REG_PRESS_MSB = 0xF7
CHIP_ID = 0x58
RESET_CMD = 0xB6
OVERSAMP_1X = 0x01
MODE_FORCED = 0x01

running = True


def _handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def _read_reg(bus, addr, reg, n=1):
    return bus.read_i2c_block_data(addr, reg, n)


def _write_reg(bus, addr, reg, val):
    bus.write_byte_data(addr, reg, val)


def _check_id(bus, addr):
    chip_id = _read_reg(bus, addr, REG_ID)[0]
    if chip_id != CHIP_ID:
        raise RuntimeError(f"Unexpected chip ID 0x{chip_id:02X}, expected 0x{CHIP_ID:02X}")


def _reset(bus, addr):
    _write_reg(bus, addr, REG_RESET, RESET_CMD)
    time.sleep(0.002)


def _configure(bus, addr):
    _write_reg(bus, addr, REG_CTRL_MEAS, (OVERSAMP_1X << 5) | MODE_FORCED)


def _read_raw(bus, addr):
    data = _read_reg(bus, addr, REG_PRESS_MSB, 6)
    raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    return raw_press


def _validate(raw):
    if raw == 0 or raw == 0xFFFFF:
        return False
    return True


def main():
    global running
    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            _check_id(bus, BMP280_ADDR)
        except OSError as e:
            print(f"Error: no device found at 0x{BMP280_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
            sys.exit(1)
        except RuntimeError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

        _reset(bus, BMP280_ADDR)
        _configure(bus, BMP280_ADDR)

        count = 0
        while running and count < 2:
            try:
                _configure(bus, BMP280_ADDR)
            except OSError as e:
                print(f"Error: failed to configure sensor: {e}", file=sys.stderr)
                sys.exit(1)

            time.sleep(0.1)
            try:
                raw = _read_raw(bus, BMP280_ADDR)
            except OSError as e:
                print(f"Error: failed to read sensor: {e}", file=sys.stderr)
                sys.exit(1)

            if not _validate(raw):
                print("Warning: invalid reading, skipping", file=sys.stderr)
            else:
                print(raw)

            count += 1
            if count < 2 and running:
                time.sleep(1.0)

    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
TIMEOUT_S = 1.0
LOOP_DELAY_S = 0.05
READ_RETRIES = 3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_data(data: str) -> bool:
    """Return True only when the data passes the device-specific validity check."""
    return data.strip() != ''


def process_data(data: str) -> None:
    """Print the validated data to stdout."""
    print(f'Received data: {data}')


def read_once(ser: serial.Serial):
    """Attempt to read one line from the serial port.

    Returns the decoded string if valid, otherwise None.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f'Serial read error: {exc}', file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        text = raw.decode('utf-8', errors='replace').strip()
    except Exception as exc:
        print(f'Decode error: {exc}', file=sys.stderr)
        return None

    if not validate_data(text):
        print('Invalid data received.', file=sys.stderr)
        return None

    return text


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUDRATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f'Failed to open serial port {PORT}: {exc}', file=sys.stderr)
        return 1
    except OSError as exc:
        print(f'Device unavailable on {PORT}: {exc}', file=sys.stderr)
        return 1

    print(f'Opened {PORT} @ {BAUDRATE} baud. Reading every {LOOP_DELAY_S}s. Ctrl-C to stop.')

    try:
        while _running:
            data = None
            for attempt in range(1, READ_RETRIES + 1):
                if not _running:
                    break
                data = read_once(ser)
                if data is not None:
                    break
                time.sleep(0.01 * attempt)

            if data is not None:
                process_data(data)

            time.sleep(LOOP_DELAY_S)
    finally:
        try:
            ser.close()
            print('Serial port closed.')
        except Exception:
            pass

    return 0


if __name__ == '__main__':
    sys.exit(main())

