import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [4, 17, 18, 22, 23, 24, 25, 27]
DELAY = 0.001

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_reading(reading: int) -> bool:
    """Return True if *reading* passes the validity check."""
    return isinstance(reading, int) and 0 <= reading <= 1


def apply_state(device: OutputDevice, state: int) -> None:
    """Apply *state* to *device* and report it."""
    device.value = bool(state)
    print(f"Pin {device.pin.number} set to {state}")


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

