                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                state = 1
                if not validate_reading(state):
                    continue
                apply_state(dev, state)
            time.sleep(DELAY)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
