from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [4, 12, 23, 24, 25, 27]
FREQUENCY = 1000
VALUE = 0.5
INTERVAL = 2.0
TIMEOUT = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = PWMOutputDevice(pin, frequency=FREQUENCY, initial_value=0)
            devices.append(dev)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
        for dev in devices:
            dev.close()
        return 1

    start = time.monotonic()

    try:
        while _running:
            elapsed = time.monotonic() - start
            if elapsed > TIMEOUT:
                print("Timeout waiting for device response.", file=sys.stderr)
                break

            for dev in devices:
                try:
                    dev.value = VALUE
                except DeviceClosed:
                    print("Device closed unexpectedly.", file=sys.stderr)
                    return 1
                except GPIOZeroError as exc:
                    print(f"Failed to set value on GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                    return 1

            print(f"PWM set to {VALUE} on pins {PINS}")

            for _ in range(int(INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


