import time
import signal
import sys

try:
    import board
    import busio
    from adafruit_mcp3xxx.mcp3008 import MCP3008
    from adafruit_mcp3xxx.analog_in import AnalogIn
except ImportError as e:
    print(f"Missing dependency: {e}", file=sys.stderr)
    sys.exit(1)

NUM_READINGS = 12
DELAY_SECONDS = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)


def read_adc(channel):
    """Read a single value from the given ADC channel.

    Returns the integer raw value (0-1023) or None on failure.
    """
    try:
        return channel.value
    except Exception as e:
        print(f"ADC read error: {e}", file=sys.stderr)
        return None


def validate(value):
    """Return True if the reading is within the valid 10-bit range."""
    return isinstance(value, int) and 0 <= value <= 1023


def main():
    # Initialize SPI bus and MCP3008
    try:
        spi = busio.SPI(clock=board.SCK, MISO=board.MISO, MOSI=board.MOSI)
        cs = board.D5
        mcp = MCP3008(spi, cs)
    except Exception as e:
        print(f"Failed to initialize MCP3008: {e}", file=sys.stderr)
        sys.exit(1)

    # Create an analog input channel (single-ended, channel 0)
    try:
        adc_channel = AnalogIn(mcp, 0)
    except Exception as e:
        print(f"Failed to create analog input: {e}", file=sys.stderr)
        sys.exit(1)

    completed = 0
    try:
        while _running and completed < NUM_READINGS:
            raw_value = read_adc(adc_channel)
            if raw_value is not None and validate(raw_value):
                print(f"Reading {completed + 1}/{NUM_READINGS}: {raw_value}")
                completed += 1
            else:
                print("Invalid reading discarded.", file=sys.stderr)

            if _running and completed < NUM_READINGS:
                time.sleep(DELAY_SECONDS)

    finally:
        # Release SPI resources
        try:
            spi.deinit()
        except Exception:
            pass

    if completed < NUM_READINGS:
        sys.exit(1)


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 4
CYCLES = 3
INTERVAL_SECONDS = 5
TIMEOUT_SECONDS = 10

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=1000, initial_value=0.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                break

            print(f"Cycle {cycle}/{CYCLES}: setting PWM duty cycle to 50%")
            pwm.value = 0.5

            deadline = time.monotonic() + TIMEOUT_SECONDS
            while _running and time.monotonic() < deadline:
                time.sleep(0.1)

            if not _running:
                break

            print(f"Cycle {cycle}/{CYCLES}: setting PWM duty cycle to 0%")
            pwm.value = 0.0

            deadline = time.monotonic() + TIMEOUT_SECONDS
            while _running and time.monotonic() < deadline:
                time.sleep(0.1)

            if _running and cycle < CYCLES:
                print(f"Cycle {cycle}/{CYCLES} complete. Waiting {INTERVAL_SECONDS} seconds...")
                deadline = time.monotonic() + INTERVAL_SECONDS
                while _running and time.monotonic() < deadline:
                    time.sleep(0.1)

        if _running:
            print("PWM control sequence completed.")
        else:
            print("Interrupted by signal; exiting early.")

    except DeviceClosed:
        print("PWM device was closed unexpectedly.", file=sys.stderr)
        return 1
    except GPIOZeroError as exc:
        print(f"GPIO error during PWM operation: {exc}", file=sys.stderr)
        return 1
    finally:
        try:
            pwm.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

