import time
import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
TIMEOUT_S = 0.5
POLL_INTERVAL_S = 0.1
READ_ATTEMPTS = 3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port():
    try:
        return serial.Serial(
            PORT,
            BAUDRATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: device not available {PORT}: {exc}", file=sys.stderr)
        return None


def read_data(ser):
    for attempt in range(1, READ_ATTEMPTS + 1):
        try:
            raw = ser.readline()
        except serial.SerialException as exc:
            print(f"Read error (attempt {attempt}/{READ_ATTEMPTS}): {exc}",
                  file=sys.stderr)
            return None
        if raw:
            text = raw.decode('ascii', errors='replace').strip()
            if text:
                return text
        else:
            print(f"Warning: no data received (attempt {attempt}/{READ_ATTEMPTS})",
                  file=sys.stderr)
    return None


def validate_data(data):
    if not data or not data.strip():
        return False
    return True


