import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 17
FREQUENCY_HZ = 1000
MIN_VALUE = 0.0
MAX_VALUE = 1.0
STEP_SECONDS = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_value(value: float) -> bool:
    return MIN_VALUE <= value <= MAX_VALUE


def apply_pwm(device: PWMOutputDevice, value: float) -> None:
    if not validate_value(value):
        raise ValueError(f"PWM value {value} out of range [{MIN_VALUE}, {MAX_VALUE}]")
    device.value = value
    print(f"PWM set to: {value}")


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=FREQUENCY_HZ, initial_value=0.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                apply_pwm(pwm, 0.5)
            except DeviceClosed:
                print("PWM device closed unexpectedly.", file=sys.stderr)
                break
            except ValueError as exc:
                print(f"Invalid PWM value: {exc}", file=sys.stderr)
            except GPIOZeroError as exc:
                print(f"GPIO error during PWM update: {exc}", file=sys.stderr)
            time.sleep(STEP_SECONDS)
    finally:
        try:
            pwm.close()
        except Exception:
            pass
        print("PWM stopped.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

