import time
import signal
import sys
from picamera2 import Picamera2

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def capture_image(picam2, filename):
    """Capture an image and save it to a file."""
    try:
        picam2.capture_file(filename)
        print(f"Image saved as {filename}")
        return True
    except Exception as e:
        print(f"Error capturing image: {e}")
        return False

def is_valid_image(filename):
    """Perform a basic validity check on the captured image file."""
    try:
        with open(filename, 'rb') as f:
            header = f.read(1024)
        # JPEG/JPG files start with 0xFFD8 and end with 0xFFD9
        if b'\xff\xd8' in header and b'\xff\xd9' in header:
            return True
        return False
    except FileNotFoundError:
        return False
    except Exception as e:
        print(f"Error checking image validity: {e}")
        return False

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = None
    try:
        picam2 = Picamera2()
        picam2.start()
        print("Camera initialized successfully.")

        cycle_count = 0
        while _running and cycle_count < 3:
            timestamp = int(time.time() * 1000)
            filename = f"image_{timestamp}.jpg"

            if capture_image(picam2, filename):
                if is_valid_image(filename):
                    print(f"Image {filename} is valid.")
                    cycle_count += 1
                else:
                    print(f"Image {filename} is not valid. Discarding.")
            else:
                print(f"Failed to capture image {filename}.")

            if _running and cycle_count < 3:
                time.sleep(1)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                print("Camera stopped.")
            except Exception as e:
                print(f"Error stopping camera: {e}")
        print("Exiting program.")

if __name__ == "__main__":
    main()

