import signal
import sys
import time

from gpiozero import Device, DigitalOutputDevice, DigitalInputDevice
from gpiozero.pins.native import NativeFactory

# BCM pin numbers for the HC-SR04 interface
TRIG_PINS = [5, 6, 17, 18, 22, 23, 24, 27]
ECHO_PINS = [5, 6, 17, 18, 22, 23, 24, 27]

# Timeout for echo pulse (max distance ~4 m => ~23 ms round trip)
ECHO_TIMEOUT_S = 0.03

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def measure_distance(trig: DigitalOutputDevice, echo: DigitalInputDevice) -> float | None:
    """Trigger one ultrasonic burst and return distance in cm, or None on timeout."""
    trig.off()
    time.sleep(0.05)

    trig.on()
    time.sleep(0.00001)
    trig.off()

    deadline = time.monotonic() + ECHO_TIMEOUT_S
    while echo.value == 0:
        if time.monotonic() > deadline:
            return None
        start = time.monotonic()

    deadline = time.monotonic() + ECHO_TIMEOUT_S
    while echo.value == 1:
        if time.monotonic() > deadline:
            return None
        stop = time.monotonic()

    elapsed = stop - start
    # Speed of sound ~343 m/s; divide by 2 for round trip
    return elapsed * 17150.0


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        factory = NativeFactory()
    except Exception as exc:
        print(f"Failed to initialize GPIO factory: {exc}", file=sys.stderr)
        return 1

    devices: list[DigitalOutputDevice | DigitalInputDevice] = []
    try:
        for trig_pin, echo_pin in zip(TRIG_PINS, ECHO_PINS):
            try:
                trig = DigitalOutputDevice(trig_pin, pin_factory=factory)
                echo = DigitalInputDevice(echo_pin, pin_factory=factory)
                devices.append(trig)
                devices.append(echo)
            except Exception as exc:
                print(f"Failed to init pins TRIG={trig_pin}, ECHO={echo_pin}: {exc}", file=sys.stderr)
                return 1

        for idx, (trig, echo) in enumerate(zip(devices[::2], devices[1::2])):
            if not _running:
                break
            dist = measure_distance(trig, echo)
            if dist is None:
                print(f"Sensor {idx}: no echo received (timeout)")
            else:
                print(f"Sensor {idx}: {dist:.2f} cm")

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        try:
            factory.close()
        except Exception:
            pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

