import serial
import time
import signal
import sys

PORT = '/dev/serial0'
BAUDRATE = 9600
READINGS = 3
INTERVAL_S = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUDRATE,
            timeout=1,
            write_timeout=1,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        completed = 0
        while _running and completed < READINGS:
            try:
                line = ser.readline()
            except serial.SerialTimeoutException as exc:
                print(f"Warning: read timeout on {PORT}: {exc}", file=sys.stderr)
                line = b''
            except serial.SerialException as exc:
                print(f"Error: serial communication failure: {exc}", file=sys.stderr)
                return 1

            if line:
                text = line.decode('utf-8', errors='replace').strip()
                if text:
                    print(text)

            completed += 1
            if _running and completed < READINGS:
                time.sleep(INTERVAL_S)

        if not _running:
            print("Interrupted by signal.", file=sys.stderr)
            return 130

        return 0
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    sys.exit(main())

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers for the HC-SR04 trigger and echo pins.
TRIGGER_PIN = 17
ECHO_PIN = 22

# gpiozero uses meters internally; convert to centimetres for display.
CM_PER_M = 100.0

# Maximum distance the HC-SR04 can reliably measure (m).
MAX_DISTANCE_M = 4.0

# Minimum distance the HC-SR04 can reliably measure (m).
MIN_DISTANCE_M = 0.02

# Time between readings (seconds).
READ_INTERVAL_S = 0.5

# Timeout waiting for a valid reading before giving up (seconds).
READ_TIMEOUT_S = 1.0


class UltrasonicSensor:
    """Thin wrapper around gpiozero.DistanceSensor for the HC-SR04."""

    def __init__(self, trigger_pin: int, echo_pin: int):
        self._sensor = None
        try:
            # max_distance keeps the sensor from issuing out-of-range reads.
            self._sensor = DistanceSensor(
                echo=echo_pin,
                trigger=trigger_pin,
                max_distance=MAX_DISTANCE_M,
            )
        except GPIOZeroError as exc:
            raise RuntimeError(f"Failed to initialise HC-SR04 on "
                               f"trigger={trigger_pin}, echo={echo_pin}: {exc}") from exc

    def get_distance_cm(self) -> float | None:
        """Return distance in cm, or None if the reading is invalid."""
        try:
            distance_m = self._sensor.distance
        except DeviceClosed:
            return None
        except GPIOZeroError:
            return None

        # gpiozero returns 0.0 when no echo is received within the timeout.
        if distance_m <= MIN_DISTANCE_M or distance_m >= MAX_DISTANCE_M:
            return None

        return round(distance_m * CM_PER_M, 2)

    def close(self) -> None:
        """Release the underlying GPIO resources."""
        if self._sensor is not None:
            try:
                self._sensor.close()
            except Exception:
                pass
            finally:
                self._sensor = None


def main() -> int:
    sensor = None
    running = True

    def _shutdown(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        sensor = UltrasonicSensor(TRIGGER_PIN, ECHO_PIN)
    except RuntimeError as exc:
        print(f"Initialisation error: {exc}", file=sys.stderr)
        return 1

    try:
        while running:
            start_time = time.monotonic()
            distance = None

            while running and distance is None:
                distance = sensor.get_distance_cm()
                if distance is None:
                    if time.monotonic() - start_time > READ_TIMEOUT_S:
                        print("Error: No valid reading received from sensor.", file=sys.stderr)
                        break
                    time.sleep(0.01)

            if distance is not None:
                print(f"Distance: {distance} cm")

            # Sleep for the remainder of the interval so readings stay ~0.5 s apart.
            elapsed = time.monotonic() - start_time
            remaining = READ_INTERVAL_S - elapsed
            if remaining > 0 and running:
                time.sleep(remaining)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        if sensor is not None:
            sensor.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

