import signal
import sys

from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17


def _check_validity(value: int) -> bool:
    """Return True if *value* is a valid digital level."""
    return value in (0, 1)


def _apply_value(pin: DigitalOutputDevice, value: int) -> None:
    """Apply *value* to *pin* and report it."""
    pin.value = value
    print(f"Pin {pin.pin.number} set to {value}")


def main() -> int:
    try:
        with DigitalOutputDevice(PIN) as pin:
            value = 1
            if not _check_validity(value):
                print("Invalid value", file=sys.stderr)
                return 1
            _apply_value(pin, value)
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\nInterrupted by user", file=sys.stderr)
        return 130
    return 0


if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys
import board
import adafruit_dht

# Global flag for graceful shutdown
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22_sensor(sensor):
    """
    Reads temperature and humidity from the DHT22 sensor.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        # adafruit_dht performs a basic plausibility check internally;
        # return None if the library reports an invalid reading.
        if temperature is None or humidity is None:
            print("Error: Sensor returned None for temperature or humidity.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # Common transient errors: checksum mismatch, timeout, or pin busy.
        print(f"RuntimeError reading DHT22: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22: {e}")
        return None, None

def main():
    global _running

    # Register signal handlers for clean termination
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 sensor on GPIO 4 (board.D4)
    try:
        dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 4: {e}")
        sys.exit(1)

    try:
        for cycle in range(3):
            if not _running:
                break

            temperature, humidity = read_dht22_sensor(dht_device)

            if temperature is not None and humidity is not None:
                print(f"Cycle {cycle + 1}/3 - Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
            else:
                print(f"Cycle {cycle + 1}/3 - Failed to retrieve valid data.")

            # Wait 5 seconds before the next reading, checking for shutdown
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # Release the underlying Linux GPIO resource cleanly
        try:
            dht_device.exit()
        except Exception:
            pass
        print("DHT22 sensor released. Exiting.")

if __name__ == "__main__":
    main()
